-- 0002_core_schema — Phase 3 core application schema (docs/data-model.md).
--
-- Purpose: create the full V1 schema — identity/tenancy, company profile &
-- preferences, tender corpus, ingestion ops, matching results, engagement
-- (saved/ignored/feedback/digests/email), billing, and ops/admin tables.
-- All CHECK/UNIQUE/FK constraints are declared at creation time (SQLite
-- CHECKs cannot be added later without a table rebuild).
--
-- Generated by drizzle-kit (0.31.x) from packages/db/src/schema/index.ts,
-- then flattened to wrangler's migration format. Date: 2026-08-14.
--
-- Destructive statement note (migration-safety rule): the single DROP below
-- removes the empty `_bootstrap` placeholder table created by 0001_init.
-- It never held data; nothing is lost.
--
-- auth_accounts / auth_sessions are deliberately absent — Better Auth
-- generates them in Phase 4 (see AUTH TABLES DECISION in
-- packages/db/src/schema/identity.ts). `users` is the Phase 3 placeholder.
DROP TABLE IF EXISTS _bootstrap;
CREATE TABLE `audit_events` (
	`id` text PRIMARY KEY NOT NULL,
	`actor_type` text NOT NULL,
	`actor_id` text,
	`organization_id` text,
	`action` text NOT NULL,
	`target_type` text NOT NULL,
	`target_id` text,
	`before_summary` text,
	`after_summary` text,
	`occurred_at` integer NOT NULL,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "ck_audit_events__actor_type" CHECK("audit_events"."actor_type" IN ('user', 'admin', 'system'))
);

CREATE INDEX `idx_audit_events__organization_id_occurred_at` ON `audit_events` (`organization_id`,`occurred_at`);
CREATE INDEX `idx_audit_events__target_type_target_id` ON `audit_events` (`target_type`,`target_id`);
CREATE TABLE `billing_events` (
	`id` text PRIMARY KEY NOT NULL,
	`stripe_event_id` text NOT NULL,
	`type` text NOT NULL,
	`organization_id` text,
	`payload_json` text NOT NULL,
	`status` text NOT NULL,
	`processed_at` integer,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "ck_billing_events__status" CHECK("billing_events"."status" IN ('received', 'processed', 'failed', 'ignored'))
);

CREATE UNIQUE INDEX `uq_billing_events__stripe_event_id` ON `billing_events` (`stripe_event_id`);
CREATE INDEX `idx_billing_events__organization_id_created_at` ON `billing_events` (`organization_id`,`created_at`);
CREATE TABLE `buyers` (
	`id` text PRIMARY KEY NOT NULL,
	`source` text NOT NULL,
	`source_buyer_id` text,
	`name` text NOT NULL,
	`country_code` text,
	`buyer_legal_type` text,
	`buyer_activity` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL
