CREATE UNIQUE INDEX `uq_buyers__source_source_buyer_id` ON `buyers` (`source`,`source_buyer_id`) WHERE "buyers"."source_buyer_id" IS NOT NULL;
CREATE INDEX `idx_buyers__source_name_country_code` ON `buyers` (`source`,`name`,`country_code`);
CREATE TABLE `company_capabilities` (
	`id` text PRIMARY KEY NOT NULL,
	`organization_id` text NOT NULL,
	`label` text NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON UPDATE no action ON DELETE no action
);

CREATE UNIQUE INDEX `uq_company_capabilities__organization_id_label` ON `company_capabilities` (`organization_id`,`label`);
CREATE TABLE `company_certifications` (
	`id` text PRIMARY KEY NOT NULL,
	`organization_id` text NOT NULL,
	`certification_code` text NOT NULL,
