);

CREATE UNIQUE INDEX `uq_company_certifications__organization_id_certification_code_label` ON `company_certifications` (`organization_id`,`certification_code`,`label`);
CREATE TABLE `company_cpv_preferences` (
	`id` text PRIMARY KEY NOT NULL,
