	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "ck_customer_feedback__verdict" CHECK("customer_feedback"."verdict" IN ('useful', 'not_useful'))
);

CREATE UNIQUE INDEX `uq_customer_feedback__organization_id_match_id` ON `customer_feedback` (`organization_id`,`match_id`);
CREATE INDEX `idx_customer_feedback__organization_id_created_at` ON `customer_feedback` (`organization_id`,`created_at`);
CREATE TABLE `digest_items` (
	`id` text PRIMARY KEY NOT NULL,
	`digest_run_id` text NOT NULL,
	`match_id` text,
	`rank` integer NOT NULL,
