);

CREATE UNIQUE INDEX `uq_digest_items__digest_run_id_match_id` ON `digest_items` (`digest_run_id`,`match_id`);
CREATE INDEX `idx_digest_items__digest_run_id` ON `digest_items` (`digest_run_id`);
CREATE INDEX `idx_digest_items__match_id` ON `digest_items` (`match_id`);
CREATE TABLE `digest_preferences` (
	`id` text PRIMARY KEY NOT NULL,
	`organization_id` text NOT NULL,
	`enabled` integer DEFAULT 1 NOT NULL,
	`send_empty` integer DEFAULT 0 NOT NULL,
	`min_classification` text DEFAULT 'WORTH_REVIEWING' NOT NULL,
	`timezone` text NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "ck_digest_preferences__min_classification" CHECK("digest_preferences"."min_classification" IN ('STRONG_MATCH', 'WORTH_REVIEWING', 'POSSIBLE_MATCH', 'LOW_FIT'))
);

CREATE UNIQUE INDEX `uq_digest_preferences__organization_id` ON `digest_preferences` (`organization_id`);
CREATE TABLE `digest_runs` (
	`id` text PRIMARY KEY NOT NULL,
